31	  void _sync(List<Pet> pets) {
32	    if (pets.isEmpty) {
33	      state = null;
34	      _initialized = false;
35	      if (_userId != null) {
36	        SharedPreferences.getInstance()
37	            .then((p) => p.remove(_prefKey(_userId!)));
38	        _userId = null;
39	      }
40	      return;
41	    }
42	
43	    if (!_initialized) {
44	      _initialized = true;
45	      _userId = Supabase.instance.client.auth.currentUser?.id;
46	      _restoreFromPrefs(pets);
47	      return;
48	    }
49	
50	    if (state != null && pets.any((p) => p.id == state!.id)) {
51	      state = pets.firstWhere((p) => p.id == state!.id);
52	      return;
53	    }
54	
55	    state = pets.first;
56	  }
