58	  Future<void> _restoreFromPrefs(List<Pet> pets) async {
59	    final prefs = await SharedPreferences.getInstance();
60	
61	    Pet? found;
62	    if (_userId != null) {
63	      final savedId = prefs.getString(_prefKey(_userId!));
64	      if (savedId != null) {
65	        for (final p in pets) {
66	          if (p.id == savedId) {
67	            found = p;
68	            break;
69	          }
70	        }
71	      }
72	    }
73	
74	    state = found ?? pets.first;
75	
76	    if (found == null && _userId != null) {
